import { InvalidTransitionError, ValidationError } from "./errors";

export const ORDER_STATES = ["placed", "paid", "packed", "shipped", "delivered", "cancelled"] as const;
export type OrderState = (typeof ORDER_STATES)[number];

/** The only allowed forward progression. */
const LIFECYCLE: readonly OrderState[] = ["placed", "paid", "packed", "shipped", "delivered"];

/** States from which an order may still be cancelled (i.e. before shipping). */
const CANCELLABLE: ReadonlySet<OrderState> = new Set<OrderState>(["placed", "paid", "packed"]);

export function isOrderState(value: unknown): value is OrderState {
  return typeof value === "string" && (ORDER_STATES as readonly string[]).includes(value);
}

export interface OrderLine {
  readonly productId: string;
  readonly quantity: number;
  readonly unitPriceCents: number;
}

export interface StateChange {
  readonly state: OrderState;
  readonly at: Date;
}

export interface OrderSnapshot {
  readonly id: string;
  readonly customerId: string;
  readonly lines: readonly OrderLine[];
  readonly totalCents: number;
  readonly state: OrderState;
  readonly history: readonly StateChange[];
  readonly createdAt: Date;
  readonly updatedAt: Date;
}

export class Order {
  private readonly history: StateChange[];

  private constructor(
    readonly id: string,
    readonly customerId: string,
    readonly lines: readonly OrderLine[],
    readonly createdAt: Date,
  ) {
    this.history = [{ state: "placed", at: createdAt }];
  }

  static place(props: {
    id: string;
    customerId: string;
    lines: readonly OrderLine[];
    now: Date;
  }): Order {
    if (!props.customerId.trim()) throw new ValidationError("Customer id is required");
    if (props.lines.length === 0) throw new ValidationError("An order must contain at least one line");
    const seen = new Set<string>();
    for (const line of props.lines) {
      if (!Number.isInteger(line.quantity) || line.quantity <= 0) {
        throw new ValidationError(`Quantity for product ${line.productId} must be a positive integer`);
      }
      if (seen.has(line.productId)) {
        throw new ValidationError(`Product ${line.productId} appears more than once in the order`);
      }
      seen.add(line.productId);
    }
    return new Order(props.id, props.customerId, props.lines.map((l) => ({ ...l })), props.now);
  }

  get state(): OrderState {
    return this.history[this.history.length - 1]!.state;
  }

  get totalCents(): number {
    return this.lines.reduce((sum, l) => sum + l.quantity * l.unitPriceCents, 0);
  }

  get isCancellable(): boolean {
    return CANCELLABLE.has(this.state);
  }

  /** The state that follows the current one, or undefined at the end of the lifecycle. */
  nextState(): OrderState | undefined {
    const index = LIFECYCLE.indexOf(this.state);
    return index >= 0 ? LIFECYCLE[index + 1] : undefined;
  }

  advanceTo(target: OrderState, now: Date): void {
    if (target === "cancelled") {
      this.cancel(now);
      return;
    }
    const expected = this.nextState();
    if (expected !== target) {
      throw new InvalidTransitionError(
        expected
          ? `Order ${this.id} is ${this.state}; it can only move to ${expected}`
          : `Order ${this.id} is ${this.state} and cannot move to ${target}`,
      );
    }
    this.history.push({ state: target, at: now });
  }

  cancel(now: Date): void {
    if (!this.isCancellable) {
      throw new InvalidTransitionError(`Order ${this.id} is ${this.state} and can no longer be cancelled`);
    }
    this.history.push({ state: "cancelled", at: now });
  }

  snapshot(): OrderSnapshot {
    return {
      id: this.id,
      customerId: this.customerId,
      lines: this.lines.map((l) => ({ ...l })),
      totalCents: this.totalCents,
      state: this.state,
      history: this.history.map((h) => ({ ...h })),
      createdAt: this.createdAt,
      updatedAt: this.history[this.history.length - 1]!.at,
    };
  }
}

