import { InsufficientStockError, ValidationError } from "./errors";

export interface ProductSnapshot {
  readonly id: string;
  readonly name: string;
  readonly priceCents: number;
  readonly onHand: number;
  readonly reserved: number;
  readonly available: number;
}

/**
 * A catalogue product together with its stock level.
 * `onHand` is physical stock in the warehouse; `reserved` is the part of it
 * held for orders that have not shipped yet.
 */
export class Product {
  private constructor(
    readonly id: string,
    readonly name: string,
    readonly priceCents: number,
    private onHand: number,
    private reserved: number,
  ) {}

  static create(props: { id: string; name: string; priceCents: number; stock: number }): Product {
    if (!props.id.trim()) throw new ValidationError("Product id is required");
    if (!props.name.trim()) throw new ValidationError("Product name is required");
    if (!Number.isInteger(props.priceCents) || props.priceCents < 0) {
      throw new ValidationError("Product price must be a non-negative integer number of cents");
    }
    if (!Number.isInteger(props.stock) || props.stock < 0) {
      throw new ValidationError("Product stock must be a non-negative integer");
    }
    return new Product(props.id, props.name, props.priceCents, props.stock, 0);
  }

  get available(): number {
    return this.onHand - this.reserved;
  }

  ensureAvailable(quantity: number): void {
    if (quantity > this.available) {
      throw new InsufficientStockError(this.id, quantity, this.available);
    }
  }

  reserve(quantity: number): void {
    assertPositiveInteger(quantity);
    this.ensureAvailable(quantity);
    this.reserved += quantity;
  }

  release(quantity: number): void {
    assertPositiveInteger(quantity);
    if (quantity > this.reserved) {
      throw new ValidationError(`Cannot release more than reserved for product ${this.id}`);
    }
    this.reserved -= quantity;
  }

  /** Reserved stock physically leaves the warehouse. */
  dispatch(quantity: number): void {
    assertPositiveInteger(quantity);
    if (quantity > this.reserved) {
      throw new ValidationError(`Cannot dispatch more than reserved for product ${this.id}`);
    }
    this.reserved -= quantity;
    this.onHand -= quantity;
  }

  snapshot(): ProductSnapshot {
    return {
      id: this.id,
      name: this.name,
      priceCents: this.priceCents,
      onHand: this.onHand,
      reserved: this.reserved,
      available: this.available,
    };
  }
}

function assertPositiveInteger(quantity: number): void {
  if (!Number.isInteger(quantity) || quantity <= 0) {
    throw new ValidationError("Quantity must be a positive integer");
  }
}

